), unique_live_names as (
 select name from public.stores group by name having count(*)=1
)
insert into public.store_locations(store_id,address,province,district,subdistrict,source_url)
select s.id,o.address,o.province,o.district,o.subdistrict,o.source_url
from official o
join unique_live_names u on u.name=o.name
join public.stores s on s.name=o.name
on conflict(store_id) do nothing;
